    protected function tearDown() {
        
    }

    public function testReordenar() {
        $menu = new menu();
        $menu->add_opcion('A');
        $menu->add_opcion('B');
        $menu->add_opcion('C');
        $menu->set_orden('A', 2);
        $menu->reordenar();

        $keys = array('B', 'C', 'A');
        $this->assertEquals($keys, array_keys($menu->get_items_array()));
    }

    public function testReordenar1() {
        $menu = new menu();
        $menu->add_opcion('A');
        $menu->add_opcion('B');
        $menu->add_opcion('C');
        $menu->set_orden('A', 0);
        $menu->set_orden('B', 1);
        $menu->set_orden('C', 2);
        $menu->reordenar();

        $keys = array('A', 'B', 'C');
        $this->assertEquals($keys, array_keys($menu->get_items_array()));
    }

    public function testReordenar2() {
        $menu = new menu();
        $menu->add_opcion('A');
        $menu->add_opcion('B');
        $menu->add_opcion('C');
        $menu->add_opcion('D');
        $menu->add_opcion('E');

        $menu->set_orden('B', 4);
        $menu->set_orden('C', 0);
        $menu->reordenar();

        $keys = array('C', 'A', 'D', 'E', 'B');
        $this->assertEquals($keys, array_keys($menu->get_items_array()));

        $menu->set_orden('B', 2);
        $menu->set_orden('C', 2);
        $menu->reordenar();
        $keys = array('A', 'B', 'C', 'D', 'E');
        $this->assertEquals($keys, array_keys($menu->get_items_array()));
    }

    public function testReordenar3() {
        $menu = new menu();
        $menu->add_opcion('A');
        $menu->set_orden('A', 0);
        $menu->reordenar();

        $keys = array('A');
        $this->assertEquals($keys, array_keys($menu->get_items_array()));
    }


    public function testReordenar4() {
        $menu = new menu();
        $menu->add_opcion('A');
        $menu->add_opcion('B');
        $menu->set_orden('A', 10);
        $menu->reordenar();
        $keys = array('B', 'A');
        $this->assertEquals($keys, array_keys($menu->get_items_array())); // A debe quedar a lo último
    }

    public function testReordenarSubmenu() {
        $menu = new menu();
        $menu->add_opcion('A');
        $menu->add_opcion('B');
        $menu->add_opcion('c1', '', 'C');
        $menu->add_opcion('c2', '', 'C');
        $menu->add_opcion('c3', '', 'C');
        $menu->add_opcion('D');
        $menu->set_orden('c1', 2);
        $menu->set_orden('c3', 0);
        $menu->reordenar();

        $keys_subitems = array('c3', 'c2', 'c1');
        $items = $menu->get_items_array();
        $subitems = array_keys($items['C']);
        $this->assertEquals($keys_subitems, $subitems);
    }

    public function testReordenarSubmenu1() {
        $menu = new menu();
        $menu->add_opcion('A');
        $menu->add_opcion('B');
        $menu->add_opcion('c1', '', 'C');
        $menu->add_opcion('c2', '', 'C');
        $menu->add_opcion('c3', '', 'C');
        $menu->add_opcion('D');
        $menu->set_orden('c1', 2);
        $menu->set_orden('c3', 0);
        $menu->set_orden('C', 0);
        $menu->set_orden('A', 3);
        $menu->reordenar();

        $keys_subitems = array('c3', 'c2', 'c1');
        $items = $menu->get_items_array();
        $subitems = array_keys($items['C']);
        $this->assertEquals($keys_subitems, $subitems);
        $keys = array('C', 'B', 'D', 'A');
        $this->assertEquals($keys, array_keys($menu->get_items_array()));
    }

    public function testReordenarError1() {
        $menu = new menu();
        $menu->add_opcion('A');
        $menu->add_opcion('B');
        $menu->add_opcion('C');
        $menu->set_orden('T', 2);
    }

    /**
     * @expectedException  \SIU\Chulupi\ErrorKernelMenu
     */
    public function testReordenarError2() {
        $menu = new menu();
        $menu->add_opcion('A');
        $menu->set_orden('A', -1);
    }
}

